UPDATE dataset
SET name = #{name}, description = #{description}, business_scene = #{businessScene},
    table_name = #{tableName}, sort = #{sort}, db_type = #{dbType}, db_host = #{dbHost},
    db_port = #{dbPort}, db_name = #{dbName}, db_username = #{dbUsername},
    db_password = #{dbPassword}, category_id = #{categoryId}, status = #{status}
WHERE id = #{id}

UPDATE table_schema
SET dataset_id = #{datasetId}, table_name = #{tableName}, table_comment = #{tableComment},
    relation_desc = #{relationDesc}, sort = #{sort}, status = #{status}
WHERE id = #{id}

UPDATE table_field
SET table_id = #{tableId}, field_name = #{fieldName}, field_type = #{fieldType},
    field_comment = #{fieldComment}, business_meaning = #{businessMeaning},
    is_metric = #{isMetric}, semantic_type = #{semanticType},
    can_query = #{canQuery}, can_agg = #{canAgg}, sort = #{sort}
WHERE id = #{id}

UPDATE metric_definition
SET name = #{name}, description = #{description}, dataset_id = #{datasetId},
    metric_code = #{metricCode}, metric_type = #{metricType},
    calculation_formula = #{calculationFormula}, sql_expression = #{sqlExpression},
    sort = #{sort}, table_id = #{tableId}, field_id = #{fieldId}, status = #{status}
WHERE id = #{id}
